// practice with rainboy
import java.io.*;
import java.util.*;

public class CF884F extends PrintWriter {
	CF884F() { super(System.out, true); }
	Scanner sc = new Scanner(System.in);
	public static void main(String[] $) {
		CF884F o = new CF884F(); o.main(); o.flush();
	}

	static final int A = 26, INF = 0x3f3f3f3f;
	int[] oo, oh; int __ = 1;
	int link(int o, int h) {
		oo[__] = o; oh[__] = h;
		return __++;
	}
	int[] ii, jj, cc, ww, ww_; int m_;
	int[] ae, dd, kk, ff; int n_;
	int[] pq, iq; int cnt;
	void init() {
		oo = new int[1 + m_ * 2]; oh = new int[1 + m_ * 2];
		ii = new int[m_]; jj = new int[m_];
		cc = new int[m_ << 1];
		ww = new int[m_]; ww_ = new int[m_];
		ae = new int[n_];
		dd = new int[n_]; kk = new int[n_]; ff = new int[n_];
		pq = new int[1 + n_]; iq = new int[n_];
		m_ = 0;
	}
	void link_(int i, int j, int c, int w) {
		int h = m_++;
		ii[h] = i; jj[h] = j; cc[h << 1] = c; ww[h] = w;
		ae[i] = link(ae[i], h << 1);
		ae[j] = link(ae[j], h << 1 | 1);
	}
	boolean less(int u, int v) {
		return dd[u] < dd[v] || dd[u] == dd[v] && kk[u] < kk[v];
	}
	int i2(int i) {
		return (i *= 2) > cnt ? 0 : i < cnt && less(pq[i + 1], pq[i]) ? i + 1 : i;
	}
	void pq_up(int u) {
		int i, j, v;
		for (i = iq[u]; (j = i / 2) > 0 && less(u, v = pq[j]); i = j)
			pq[iq[v] = i] = v;
		pq[iq[u] = i] = u;
	}
	void pq_dn(int u) {
		int i, j, v;
		for (i = iq[u]; (j = i2(i)) > 0 && less(v = pq[j], u); i = j)
			pq[iq[v] = i] = v;
		pq[iq[u] = i] = u;
	}
	void pq_add_last(int u) {
		pq[iq[u] = ++cnt] = u;
	}
	int pq_remove_first() {
		int u = pq[1], v = pq[cnt--];
		if (v != u) {
			iq[v] = 1; pq_dn(v);
		}
		iq[u] = 0;
		return u;
	}
	boolean dijkstra(int s, int t) {
		Arrays.fill(dd, INF);
		dd[s] = 0; pq_add_last(s);
		while (cnt > 0) {
			int i = pq_remove_first();
			int k = kk[i] + 1;
			for (int o = ae[i]; o != 0; o = oo[o]) {
				int h_ = oh[o];
				if (cc[h_] > 0) {
					int h = h_ >> 1;
					int j = i ^ ii[h] ^ jj[h];
					int d = dd[i] + ((h_ & 1) == 0 ? ww_[h] : -ww_[h]);
					if (dd[j] > d || dd[j] == d && kk[j] > k) {
						if (dd[j] == INF)
							pq_add_last(j);
						dd[j] = d; kk[j] = k; ff[j] = h_;
						pq_up(j);
					}
				}
			}
		}
		return dd[t] != INF;
	}
	int trace(int s, int t) {
		while (t != s) {
			int h_ = ff[t], h = h_ >> 1;
			cc[h_]--; cc[h_ ^ 1]++;
			t ^= ii[h] ^ jj[h];
		}
		return 1;
	}
	int edmonds_karp(int s, int t) {
		for (int h = 0; h < m_; h++) {
			int i = ii[h], j = jj[h];
			dd[j] = Math.min(dd[j], dd[i] + ww[h]);
		}
		for (int h = 0; h < m_; h++) {
			int i = ii[h], j = jj[h];
			ww_[h] = ww[h] + dd[i] - dd[j];
		}
		int f = 0;
		while (dijkstra(s, t)) {
			f += trace(s, t);
			for (int h = 0; h < m_; h++) {
				int i = ii[h], j = jj[h];
				if (dd[i] != INF && dd[j] != INF) {
					// dd[j] <= dd[i] + ww_[h]
					// ww_[h] + dd[i] - dd[j] >= 0
					ww_[h] += dd[i] - dd[j];
				}
			}
		}
		int cost = 0;
		for (int h = 0; h < m_; h++)
			cost += ww[h] * cc[h << 1 | 1];
		return cost;
	}
	void main() {
		int n = sc.nextInt() / 2;
		n_ = 1 + n + A + 1;
		m_ = n + n * A + A;
		init();
		byte[] cc = sc.next().getBytes();
		int[] bb = new int[n * 2];
		for (int i = 0; i < n * 2; i++)
			bb[i] = sc.nextInt();
		for (int i = 0; i < n; i++)
			link_(0, 1 + i, 2, 0);
		for (int i = 0; i < n; i++) {
			int j = n * 2 - 1 - i;
			int ai = cc[i] - 'a';
			int aj = cc[j] - 'a';
			for (int a = 0; a < A; a++) {
				int b;
				if (a == ai && a == aj)
					b = Math.max(bb[i], bb[j]);
				else if (a == ai)
					b = bb[i];
				else if (a == aj)
					b = bb[j];
				else
					b = 0;
				link_(1 + i, 1 + n + a, 1, -b);
			}
		}
		int[] kk = new int[A];
		for (int i = 0; i < n * 2; i++) {
			int a = cc[i] - 'a';
			kk[a]++;
		}
		for (int a = 0; a < A; a++)
			link_(1 + n + a, n_ - 1, kk[a], 0);
		println(-edmonds_karp(0, n_ - 1));
	}
}

